import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·23","description":"易小帖 - 卷五·23","frontmatter":{"title":"卷五·23","description":"易小帖 - 卷五·23"},"headers":[],"relativePath":"classics/yixiaotie/145.md","filePath":"classics/yixiaotie/145.md"}'),o={name:"classics/yixiaotie/145.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·23",tabindex:"-1"},[r("卷五·23 "),e("a",{class:"header-anchor",href:"#卷五·23","aria-label":"Permalink to “卷五·23”"},"​")],-1),e("p",null,"此即推易法，與春秋太史占筮並無不合。特其說有未當者。既曰坎艮，則不俟推測而即知為鼠，何則？夫子明曰坎為豖，艮為狗為鼠，則未有狗豖而可入匣者，此不必以隱盜顯拘從卦象求也。況既變噬嗑，則更與黔喙之屬有明證者乎。第鼠必不死。梁武與闖公各有誤者，舍蹇而之噬嗑，則蹇足雖不行，而噬口尚能囓，不死也。去坎陷艮止而就燥與動，則燥出瀆閟，動可決行，又不死也。且艮為鬼㝠門，死象也。今乃變而為震之反生，夫反生非生乎，又不死也。然且鼠者艮也，今改艮鼠而為震，則鼠亡矣。亡鼠宜死，乃觀其同功，而自二至四，嵬然一艮，高出於離震之間，未亡也。又不死也。若雲荷校滅耳，則坎為耳，坎受滅艮不受滅。雲日中則昃，則蹇有互離，噬嗑有小離大離，三日遞出，並未嘗昃，況他物畏日昃，鼠不畏日昃也。至雲逮晚鼠死，則在射後矣。射者當前之是射與後何涉？此必當時傅會帝與公者，故為是言以飾之而不知其無是理也。至若金盛數四之說，則更屬大謬。春秋太史並無有以時氣佔易者。自臨之八月，復之七日，偶及月日，而漢後易家遂有十二闢卦，及緯書六日七分卦氣直日之說。然總非古法。且於諸事並未一驗，故一概屏去。今即以其言按之，覺有大荒唐者。據焦氏卦氣直日，則蹇為立秋，七月之卦。然兌初用事，並非金盛月也。若噬嗑則已在夏四月中矣。至京房卦氣直日，則蹇在大雪十二月中。噬嗑在立冬十月節，並無秋金，與《唐書‧》律歴志所載並同。而後儒作循環變通諸法，則更以噬嗑為木道，蹇困為火行金，且無有，何有於四。如以卦言，則蹇與噬嗑並無一兌，兌四之數於何見之。子所言固不謬耳。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
